import {settings,beam,graph,radiation,rfField} from './research-engine.js';
const $=id=>document.getElementById(id),mint='#91dfc8',copper='#efa76f';let run=null,scan=[],memory=null,network=null,index=0,playing=true,orbit=true,angle=.6,tilt=.25,selected=0,points=[],last=0,paint=0,busy=false;
const worker=new Worker('./research-worker.js',{type:'module'});
const controls=['assembly','hand','twist','separation','j','pol','ell','waist','offset','drive','gamma'];
function params(){return {assembly:$('assembly').value,hand:+$('hand').value,twist:+$('twist').value,separation:+$('separation').value,j:+$('j').value/1000,pol:$('pol').value,ell:+$('ell').value,waist:+$('waist').value,offset:+$('offset').value,drive:+$('drive').value/1000,gamma:+$('gamma').value/1000};}
function labels(){for(let [id,unit,mul] of [['twist','°',1],['separation',' nm',1],['j',' meV',1],['offset',' w₀',1],['drive',' meV',1],['gamma',' fs⁻¹',.001]])$(id+'Out').textContent=(+$ (id).value*mul)+unit;}
function lock(v){busy=v;$('run').disabled=v;$('compare').disabled=v;controls.forEach(id=>$(id).disabled=v);$('reset').disabled=v;}
function compute(){lock(true);$('status').textContent='Solving quantum dynamics + eigenstate scan…';worker.postMessage({type:'run',p:params()});}
worker.onmessage=({data})=>{lock(false);if(data.type==='error'){$('status').textContent='Solver error: '+data.message;return;}if(data.type==='compare'){memory=data.data;$('memoryLabel').textContent='Copper: population difference · mint: state distance';$('status').textContent='X / Y comparison ready · 2 independently computed runs';return;}run=data.run;scan=data.scan;memory=null;index=0;selected=0;playing=true;$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause playback');network=graph(run.m,+$('threshold').value/1000);$('memoryLabel').textContent='Press “Compare X / Y input encoding”';$('status').textContent='Computed · '+run.frames.length+' frames · '+run.m.p.dt.toFixed(3)+' fs RK4';$('sceneTitle').textContent={helix:'One helix. Many coupled states.',monomer:'Start at one effective chromophore.',dimer:'Two sites begin to interact.',bundle:'Three helices share an excitation.',network:'A junction motif connects local states.'}[run.m.p.assembly];let p=run.m.p;$('insight').textContent=p.ell!==0&&p.offset===0?'At the vortex core, the field vanishes on axis. This nanoscale assembly samples a tiny fraction of the '+p.waist+' nm beam waist. A weak response is physically meaningful. Move the beam offset toward its bright ring to compare.':'Each site samples the actual spatial beam phase and amplitude. Geometry sets the coupling Hamiltonian; the master equation then determines populations, coherence and coherent radiation. The drawing is fixed during each run.';};
worker.onerror=e=>{lock(false);$('status').textContent='Worker failed: '+e.message;};
controls.forEach(id=>$(id).addEventListener('input',()=>{labels();$('status').textContent='Pending settings · compute to update all linked views';}));$('run').onclick=compute;$('compare').onclick=()=>{if(!run)return;lock(true);$('status').textContent='Computing X and Y input trajectories for the displayed run…';worker.postMessage({type:'compare',p:run.m.p});};$('reset').onclick=()=>{for(let id of controls){let val=settings[id];if(['j','drive','gamma'].includes(id))val*=1000;$(id).value=val;}labels();compute();};
function surface(id){let c=$(id),r=c.getBoundingClientRect(),q=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(r.width*q)||c.height!==Math.round(r.height*q)){c.width=Math.round(r.width*q);c.height=Math.round(r.height*q);}let x=c.getContext('2d');x.setTransform(q,0,0,q,0,0);x.clearRect(0,0,r.width,r.height);return [x,r.width,r.height];}
function line(c,ps,color,width=1){c.beginPath();ps.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.strokeStyle=color;c.lineWidth=width;c.stroke();}
function text(c,t,x,y,color='#8aaba3',size=10){c.fillStyle=color;c.font=size+'px system-ui';c.fillText(t,x,y);}
function scene(f){let [c,w,h]=surface('assemblyCanvas'),g=run.m.g,extent=Math.max(3,...g.map(s=>Math.hypot(...s.r))),scale=Math.min(w/(extent*2+3),h/(extent*2+3)),proj=r=>{let [x,y,z]=r,xx=x*Math.cos(angle)-y*Math.sin(angle),yy=x*Math.sin(angle)+y*Math.cos(angle);return [w*.48+xx*scale,h*.52-(z*Math.cos(tilt)-yy*Math.sin(tilt))*scale,yy*Math.cos(tilt)+z*Math.sin(tilt)];};for(let k=-6;k<=6;k++){line(c,[proj([k,-6,-extent-1]),proj([k,6,-extent-1])],'#29463855');line(c,[proj([-6,k,-extent-1]),proj([6,k,-extent-1])],'#29463855');}
points=g.map((s,i)=>({i,q:proj(s.r)}));for(let group=0;group<=Math.max(...g.map(s=>s.group));group++){let pts=g.filter(s=>s.group===group).map(s=>proj(s.r));if(pts.length>1){line(c,pts,'#5c987b30',8);line(c,pts,'#80b59466',1);}}
for(let [i,j] of network.edges){let a=points[i].q,b=points[j].q,L=run.m.d**2,coh=Math.hypot(f.rho[(i+1)*run.m.d+j+1],f.rho[L+(i+1)*run.m.d+j+1]);line(c,[a,b],`rgba(145,223,200,${Math.min(.8,.12+coh*5)})`,.5+coh*8);}
for(let {i,q} of [...points].sort((a,b)=>a.q[2]-b.q[2])){let s=g[i],pop=Math.max(0,f.pop[i]),e=Math.min(1,pop*12),r=7+scale*.025;let glow=c.createRadialGradient(q[0],q[1],0,q[0],q[1],r*5);glow.addColorStop(0,`rgba(239,167,111,${e*.6})`);glow.addColorStop(1,'#efa76f00');c.fillStyle=glow;c.fillRect(q[0]-r*5,q[1]-r*5,r*10,r*10);let grad=c.createRadialGradient(q[0]-3,q[1]-3,0,q[0],q[1],r);grad.addColorStop(0,e>.03?'#fff0d0':'#a8dac0');grad.addColorStop(.4,e>.03?copper:'#4b7e65');grad.addColorStop(1,'#183229');c.fillStyle=grad;c.beginPath();c.arc(q[0],q[1],r,0,Math.PI*2);c.fill();let tip=proj(s.r.map((x,k)=>x+.55*s.mu[k]));line(c,[q,tip],mint,1.2);text(c,String(i+1).padStart(2,'0'),q[0]+r+5,q[1]+3);if(i===selected){c.beginPath();c.arc(q[0],q[1],r+5,0,7);c.strokeStyle=copper;c.stroke();}}
let origin=[w-70,90];for(let [v,label,col] of [[[1,0,0],'x',copper],[[0,1,0],'y',mint],[[0,0,1],'z','#93b8ff']]){let p=proj(v),o=proj([0,0,0]),tip=[origin[0]+(p[0]-o[0])*.6,origin[1]+(p[1]-o[1])*.6];line(c,[origin,tip],col);text(c,label,tip[0]+4,tip[1],col);}
$('siteLabel').textContent='SITE '+String(selected+1).padStart(2,'0');$('selectedPopulation').textContent=f.pop[selected].toPrecision(3);$('selectedPhase').textContent=f.amp[selected]>1e-8?'arg ρᵢ₀ = '+f.phase[selected].toFixed(2)+' rad':'Phase undefined';$('stage').textContent=f.t<30?'GROUND STATE / PULSE ARRIVING':f.t<140?'OPTICAL EXCITATION':'COHERENCE EVOLUTION & DECAY';}
function beamView(){let [c,w,h]=surface('beamCanvas'),p=run.m.p,N=56,size=Math.min(w,h-22),left=(w-size)/2;for(let iy=0;iy<N;iy++)for(let ix=0;ix<N;ix++){let x=(ix/N-.5)*4*p.waist,y=(.5-iy/N)*4*p.waist,[a,b]=beam(x,y,0,{...p,offset:0}),v=a*a+b*b,phase=Math.atan2(b,a)*180/Math.PI;c.fillStyle=`hsl(${phase+180} 65% ${Math.min(68,3+Math.sqrt(v)*65)}%)`;c.fillRect(left+ix*size/N,iy*size/N,size/N+1,size/N+1);}let cross=left+size/2-p.offset*size/4;line(c,[[cross-5,size/2],[cross+5,size/2]],'#fff');line(c,[[cross,size/2-5],[cross,size/2+5]],'#fff');text(c,'−2w₀',left,size+16);text(c,'+2w₀',left+size-30,size+16);$('beamLabel').textContent='ℓ = '+p.ell+' · w₀ '+p.waist+' nm';}
function rhoView(f){let [c,w,h]=surface('rhoCanvas'),n=run.m.p.n,d=run.m.d,L=d*d,max=Math.max(...f.pop,1e-14),s=Math.min(w-20,h-25)/n,left=(w-s*n)/2;for(let i=0;i<n;i++)for(let j=0;j<n;j++){let q=(i+1)*d+j+1,a=Math.min(1,Math.hypot(f.rho[q],f.rho[L+q])/max);c.fillStyle=`rgb(${20+210*a},${40+125*a},${32+77*a})`;c.fillRect(left+j*s+1,10+i*s+1,s-2,s-2);}$('rhoScale').textContent='0–'+max.toExponential(2);}
function radiationView(f){let [c,w,h]=surface('radiationCanvas'),nx=56,ny=28,vals=[],max=0;for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){let th=(y+.5)/ny*Math.PI,ph=x/nx*2*Math.PI,v=radiation(run.m,f,[Math.sin(th)*Math.cos(ph),Math.sin(th)*Math.sin(ph),Math.cos(th)]).intensity;vals.push(v);max=Math.max(max,v);}for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){let v=max>1e-18?Math.sqrt(vals[y*nx+x]/max):0;c.fillStyle=`rgb(${10+140*v},${28+193*v},${26+168*v})`;c.fillRect(x*w/nx,15+y*(h-40)/ny,w/nx+1,(h-40)/ny+1);}text(c,'θ = 0',5,11);text(c,'0                 φ / azimuth                 2π',6,h-6);$('radScale').textContent='Peak '+max.toExponential(2)+' a.u.';}
function chart(id,series,colors,xMin,xMax,marker=null,log=false){let [c,w,h]=surface(id),all=series.flat().filter(p=>p[1]!==null&&Number.isFinite(p[1])),vals=all.map(p=>log?Math.log10(1+p[1]):p[1]),max=Math.max(...vals,1e-6),min=Math.min(...vals,0),X=x=>35+(x-xMin)/(xMax-xMin)*(w-48),Y=y=>h-25-((log?Math.log10(1+y):y)-min)/(max-min)*(h-45);for(let i=0;i<4;i++){let v=min+(max-min)*i/3,yy=h-25-i/3*(h-45);line(c,[[35,yy],[w-12,yy]],'#2a4137');text(c,v.toPrecision(2),0,yy+3,undefined,9);}series.forEach((s,k)=>{let segment=[];for(let p of s){if(p[1]===null||!Number.isFinite(p[1])){if(segment.length)line(c,segment,colors[k],1.5);segment=[];}else segment.push([X(p[0]),Y(p[1])]);}if(segment.length)line(c,segment,colors[k],1.5);});for(let i=0;i<=4;i++){let x=xMin+(xMax-xMin)*i/4;text(c,x.toFixed(0),X(x)-5,h-5,undefined,9);}if(marker!==null)line(c,[[X(marker),12],[X(marker),h-25]],'#e8ebd999');}
function clocks(f){let [c,w,h]=surface('clockCanvas'),cx=w/2,cy=h/2,R=Math.min(w,h)*.36,n=run.m.p.n,max=Math.max(...f.amp,1e-12),ps=Array.from({length:n},(_,i)=>[cx+R*Math.cos(i/n*2*Math.PI-Math.PI/2),cy+R*Math.sin(i/n*2*Math.PI-Math.PI/2)]);for(let [a,b] of network.edges)line(c,[ps[a],ps[b]],'#47745b66');ps.forEach(([x,y],i)=>{let r=5+14*f.amp[i]/max;c.strokeStyle=mint;c.beginPath();c.arc(x,y,r,0,7);c.stroke();if(f.amp[i]>1e-8)line(c,[[x,y],[x+r*Math.cos(f.phase[i]),y-r*Math.sin(f.phase[i])]],copper,1.8);text(c,i+1,x-3,y+r+12,undefined,9);});$('order').textContent='Alignment R = '+f.order.toFixed(3);}
function topology(){let [c,w,h]=surface('lapCanvas'),s=network.spectrum,max=Math.max(...s,1),bw=(w-20)/s.length;s.forEach((v,i)=>{c.fillStyle=v<1e-8?copper:mint;c.fillRect(10+i*bw,h-22-Math.max(2,v/max*(h-40)),bw-4,Math.max(2,v/max*(h-40)));text(c,Math.abs(v)<1e-8?'0':v.toFixed(1),10+i*bw,h-7,undefined,9);});$('components').textContent=network.components;$('cycles').textContent=network.cycles;$('edges').textContent=network.edges.length;}
function rf(){let [c,w,h]=surface('rfCanvas'),b0=Math.max(0,+$('bias').value||0),b1=Math.max(0,+$('rfAmplitude').value||0),freq=Math.max(.1,+$('rfFrequency').value||.1),kind=$('rfKind').value,period=1000/freq;let max=Math.max(.01,b0+b1),X=t=>35+t/(2*period)*(w-48),Y=v=>h/2-v/max*(h*.3);for(let k=0;k<3;k++){let pts=Array.from({length:201},(_,i)=>{let t=i/200*2*period;return [X(t),Y(rfField(t,kind,b0,b1,freq/1000)[k])];});line(c,pts,[copper,mint,'#93b8ff'][k],1.7);}line(c,[[35,h/2],[w-10,h/2]],'#426153');text(c,'Bx',20,15,copper);text(c,'By',55,15,mint);text(c,'Bz',90,15,'#93b8ff');text(c,'±'+max.toFixed(2)+' mT',w-100,15);text(c,'0 ns',30,h-8);text(c,(2*period).toPrecision(4)+' ns',w-90,h-8);}
function draw(){rf();if(!run)return;let f=run.frames[Math.min(250,Math.floor(index))];scene(f);rhoView(f);beamView();radiationView(f);clocks(f);topology();chart('traceCanvas',[run.frames.map(f=>[f.t,f.excited]),run.frames.map(f=>[f.t,f.coherence]),run.frames.map(f=>[f.t,f.pulse])],[copper,mint,'#6c8382'],0,500,f.t);chart('metricCanvas',[scan.map(p=>[p.twist,p.metric])],[mint],25,100,run.m.p.twist,true);$('metricScale').textContent='Vertical: log₁₀(1 + gθθ)';if(memory)chart('memoryCanvas',[memory.map(p=>[p.t,p.distance]),memory.map(p=>[p.t,p.populationDifference])],[mint,copper],0,500,f.t);else{let [c,w,h]=surface('memoryCanvas');text(c,'Two inputs. One material. A measurable difference.',20,h/2);text(c,'Run the X / Y comparison to calculate this panel.',20,h/2+23,undefined,11);}$('time').textContent=f.t+' fs';$('scrub').value=Math.floor(index);$('pop').textContent=f.excited<.001?f.excited.toExponential(2):f.excited.toFixed(3);$('part').textContent=f.pr.toFixed(2);$('coh').textContent=f.coherence<.001?f.coherence.toExponential(2):f.coherence.toFixed(3);}
function tick(now){let dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(run&&playing){index+=dt*24;if(index>=250){index=250;playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','Play trajectory');}}if(orbit)angle+=dt*.12;if(now-paint>65){draw();paint=now;}requestAnimationFrame(tick);}requestAnimationFrame(tick);
$('play').onclick=()=>{if(index>=250)index=0;playing=!playing;$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause playback':'Play trajectory');};$('replay').onclick=()=>{index=0;playing=true;$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause playback');};$('scrub').oninput=()=>{index=+$('scrub').value;playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','Play trajectory');};$('orbit').onclick=()=>{orbit=!orbit;$('orbit').setAttribute('aria-pressed',orbit);};$('threshold').oninput=()=>{$('thresholdOut').textContent=$('threshold').value+' meV';if(run)network=graph(run.m,+$('threshold').value/1000);};
let drag=null;$('assemblyCanvas').onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,sx:e.clientX,sy:e.clientY};$('assemblyCanvas').setPointerCapture(e.pointerId);};$('assemblyCanvas').onpointermove=e=>{if(!drag)return;angle+=(e.clientX-drag.x)*.01;tilt=Math.max(-1,Math.min(1,tilt+(e.clientY-drag.y)*.006));drag.x=e.clientX;drag.y=e.clientY;};$('assemblyCanvas').onpointerup=e=>{if(drag&&Math.hypot(e.clientX-drag.sx,e.clientY-drag.sy)<5){let r=$('assemblyCanvas').getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,pt=[...points].sort((a,b)=>Math.hypot(a.q[0]-x,a.q[1]-y)-Math.hypot(b.q[0]-x,b.q[1]-y))[0];if(pt&&Math.hypot(pt.q[0]-x,pt.q[1]-y)<30)selected=pt.i;}drag=null;};
$('export').onclick=()=>{if(!run)return;let payload={schema:'p1h11-research-v0.2',chemicalIdentity:'User supplied (S)-phenyl-hexadecanoylamino-acetic acid methyl ester',scope:'Assumed packing and effective electronic parameters. RF waveform preview is not coupled. Radiation is dimensionless coherent far-field only.',parameters:run.m.p,geometry:run.m.g,Hamiltonian:Array.from(run.m.H),frames:run.frames,quantumMetric:scan,graph:{thresholdMeV:+$('threshold').value,...network},inputComparison:memory};let u=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='P1H11-research-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
$('close').onclick=()=>$('dialog').close();$('checks').onclick=async()=>{try{let r=await fetch('research-validation.json').then(r=>r.json());$('dialogBody').innerHTML='<div class="eyebrow">NUMERICAL VERIFICATION / v0.2</div><h2>'+r.tests.length+' checks · '+r.status+'</h2><p>'+r.scope+'</p><table><tr><th>Test</th><th>Error / metric</th><th>Tolerance</th></tr>'+r.tests.map(t=>'<tr><td>'+t.name+'</td><td>'+t.value.toExponential(2)+'</td><td>'+t.tolerance.toExponential(1)+'</td></tr>').join('')+'</table><p>Passing numerical checks does not calibrate this model to P1H11 experiments.</p>';$('dialog').showModal();}catch(e){$('status').textContent='Validation report unavailable: '+e.message;}};labels();compute();
